// Valida a assinatura HMAC enviada pelo FluxoIA
const crypto = require('crypto');
const secret = $env.FLUXOIA_WEBHOOK_SECRET;
const item = $input.first();
const h = item.json.headers;
const ts = h['x-fluxoia-timestamp'];
const sig = (h['x-fluxoia-signature'] || '').replace('sha256=', '');
const raw = JSON.stringify(item.json.body);
const expected = crypto.createHmac('sha256', secret).update(ts + '.' + raw).digest('hex');
if (!ts || Math.abs(Date.now() - Number(ts)) > 5 * 60 * 1000) throw new Error('Evento expirado');
if (expected !== sig) throw new Error('Assinatura inválida');
const body = item.json.body;
const payload = JSON.stringify({ execution_id: body.execution_id, request_id: body.request_id });
const now = String(Date.now());
const outSig = 'sha256=' + crypto.createHmac('sha256', secret).update(now + '.' + payload).digest('hex');
return [{ json: { execution_id: body.execution_id, request_id: body.request_id, payload, ts: now, sig: outSig } }];

// Monta o callback assinado com o resultado
const crypto = require('crypto');
const secret = $env.FLUXOIA_WEBHOOK_SECRET;
const prev = $('Validar evento').first().json;
const res = $input.first().json;
const ok = res.statusCode === 200 && res.body && res.body.ok;
const payload = JSON.stringify({ execution_id: prev.execution_id, status: ok ? 'concluida' : 'falhou', error: ok ? undefined : String((res.body && res.body.error) || ('HTTP ' + res.statusCode)).slice(0, 900), notification_sent: false });
const ts = String(Date.now());
const sig = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + payload).digest('hex');
return [{ json: { payload, ts, sig, ok, result: ok ? res.body.result : null } }];
